import CodeSpan from "../CodeSpan";
import Token from "../Token";
import ASTVisitor from "./ASTVisitor";
/**
 * @category AST
 */
export default abstract class ASTNode {
    constructor();
    abstract tokens: {
        [key: string]: Token | Token[] | null;
    };
    abstract accept<R>(visitor: ASTVisitor<R>): R;
    get span(): CodeSpan;
}
